import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse(`{"title":"Page 14 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"14","title":"Page 14 | Home","prev":"/page/13/","next":"/page/15/","posts":[{"title":"在浏览器上显示TIF图像","url":"/posts/2020-09-10-show-tif-in-web/","date":"2020-09-10 20:57","tags":["tif"],"html":"<p>在实际的业务中，我们需要在浏览器中对 TIF 文件的某个区域进行选择，所以需要展示 TIF 文件在浏览器中。不过浏览器并不能直接支持 TIF 格式，所以我们需要做相应的处理。</p>\\n<h2 id=\\"寻找合适的解析库\\" tabindex=\\"-1\\">寻找合适的解析库 <a class=\\"header-anchor\\" href=\\"#寻找合适的解析库\\" aria-label=\\"Permalink to &quot;寻找合适的解析库&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>图像处理是一个很复杂的事情，如果别人有实现就别自己造轮子了。这里我推荐<a href=\\"https://github.com/photopea/UTIF.js/\\" target=\\"_blank\\" rel=\\"noreferrer\\">UTIF.js</a>，这位作者实现了网页版图片编辑器。所以质量上还是很高的。</p>\\n<h2 id=\\"导入图片二进制数据\\" tabindex=\\"-1\\">导入图片二进制数据 <a class=\\"header-anchor\\" href=\\"#导入图片二进制数据\\" aria-label=\\"Permalink to &quot;导入图片二进制数据&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们需要把图片导入成二进制数据，我们使用<code>fetch</code>来获取图片二进制数据，fetch 本身就可以返回二进制数据，大致代码如下：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">  fetchImage</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    fetch</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"bali.tif\\"</span><span style=\\"color:#24292E\\">)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      .</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">response</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">!</span><span style=\\"color:#24292E\\">response.ok) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">          throw</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> Error</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"Network response was not ok\\"</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#24292E\\"> response.</span><span style=\\"color:#6F42C1\\">arrayBuffer</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      })</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      .</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">data</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        const</span><span style=\\"color:#005CC5\\"> ifds</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#005CC5\\"> UTIF</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">decode</span><span style=\\"color:#24292E\\">(data);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">        UTIF</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">decodeImage</span><span style=\\"color:#24292E\\">(data, ifds[</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        const</span><span style=\\"color:#005CC5\\"> rgba</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#005CC5\\"> UTIF</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">toRGBA8</span><span style=\\"color:#24292E\\">(ifds[</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        const</span><span style=\\"color:#005CC5\\"> widh</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> ifds[</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">].width;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        const</span><span style=\\"color:#005CC5\\"> height</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> ifds[</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">].height;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        const</span><span style=\\"color:#005CC5\\"> canvas</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> document.</span><span style=\\"color:#6F42C1\\">createElement</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"canvas\\"</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        canvas.width </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> widh;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        canvas.height </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> height;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">        this</span><span style=\\"color:#24292E\\">.width </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> widh;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">        this</span><span style=\\"color:#24292E\\">.height </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> height;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        const</span><span style=\\"color:#005CC5\\"> ctx</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> canvas.</span><span style=\\"color:#6F42C1\\">getContext</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"2d\\"</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        const</span><span style=\\"color:#005CC5\\"> imgData</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> ImageData</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">          new</span><span style=\\"color:#6F42C1\\"> Uint8ClampedArray</span><span style=\\"color:#24292E\\">(rgba.buffer),</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          widh,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          height</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        ctx?.</span><span style=\\"color:#6F42C1\\">putImageData</span><span style=\\"color:#24292E\\">(imgData, </span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        canvas.</span><span style=\\"color:#6F42C1\\">toBlob</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">blob</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">          this</span><span style=\\"color:#24292E\\">.imgData </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> URL</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">createObjectURL</span><span style=\\"color:#24292E\\">(blob);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br></div></div><p>导入的二进制数据，使用<code>UTIF</code>去解码二进制数据。拿到图片的基本信息之后，创建相应的 canvas 画布，把图片数据加载进 canvas 之后可以创建<code>ObjectURL</code>就可以使用<code>img</code> tag 来显示。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>处理 TIF 文件本身并不是很复杂，在于找到合适的方法。完整的演示代码在<a href=\\"https://github.com/acgotaku/vue-tif\\" target=\\"_blank\\" rel=\\"noreferrer\\">vue-tif</a>。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://github.com/photopea/UTIF.js/\\" target=\\"_blank\\" rel=\\"noreferrer\\">UTIF.js</a></p>\\n<p><a href=\\"https://github.com/acgotaku/vue-tif\\" target=\\"_blank\\" rel=\\"noreferrer\\">vue-tif</a></p>\\n"},{"title":"简单多边形的判定","url":"/posts/2020-08-09-simple-polygon/","date":"2020-08-09 14:50","tags":["algorithm"],"html":"<p>在实际工作中，需要在照片上选定一个范围，这个范围是个多边形，并且是个简单多边形，我们需要判定是否是个合法的简单多边形，主要判定的是任意两边不能交叉。</p>\\n<h2 id=\\"判断两条线段相交\\" tabindex=\\"-1\\">判断两条线段相交 <a class=\\"header-anchor\\" href=\\"#判断两条线段相交\\" aria-label=\\"Permalink to &quot;判断两条线段相交&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们可以借助向量的知识来判断两个线段是否相交。二维向量的叉乘(cross product)的几何意义是以两向量为邻边的平行四边形的面积。此外，定义两个向量 a, b。\\n当 <code>aXb &lt; 0</code>, b 对应的线段，在 a 的顺时针方向。当 <code>aXb = 0</code>时， a 与 b 共线。当 <code>aXb &gt; 0</code>，b 在 a 的逆时针方向。\\n如果两条线段相交，那必然一条线段的终点和起点，在另外一条线段的两侧。</p>\\n<h2 id=\\"判断多边形两边是否相交\\" tabindex=\\"-1\\">判断多边形两边是否相交 <a class=\\"header-anchor\\" href=\\"#判断多边形两边是否相交\\" aria-label=\\"Permalink to &quot;判断多边形两边是否相交&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>简单并且暴力的方法是检测任意两边是否有交点，在复杂度不高的情况下可以使用这种方法。但是显然是有更优解的，目前比较有名的两个算法是 <code>The Bentley-Ottmann Algorithm</code> 和\\n<code>The Shamos-Hoey Algorithm</code>。算法的细节请查看下方的参考，我就不详细描述了。</p>\\n<h2 id=\\"简单多边形判定的实现\\" tabindex=\\"-1\\">简单多边形判定的实现 <a class=\\"header-anchor\\" href=\\"#简单多边形判定的实现\\" aria-label=\\"Permalink to &quot;简单多边形判定的实现&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> interface</span><span style=\\"color:#6F42C1\\"> Point</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  x</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  y</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> interface</span><span style=\\"color:#6F42C1\\"> Line</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  start</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Point</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  end</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Point</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> samePoint</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">p1</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Point</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">p2</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Point</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (p1.x </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#24292E\\"> p2.x </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#24292E\\"> p1.y </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#24292E\\"> p2.y) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  } </span><span style=\\"color:#D73A49\\">else</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> signedArea</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">p1</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Point</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">p2</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Point</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">p3</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Point</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> (p1.x </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#24292E\\"> p3.x) </span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#24292E\\"> (p2.y </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#24292E\\"> p3.y) </span><span style=\\"color:#D73A49\\">></span><span style=\\"color:#24292E\\"> (p2.x </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#24292E\\"> p3.x) </span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#24292E\\"> (p1.y </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#24292E\\"> p3.y);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> intersectLine</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">l1</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Line</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">l2</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Line</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // consecutive edge return false</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    samePoint</span><span style=\\"color:#24292E\\">(l1.start, l2.start) </span><span style=\\"color:#D73A49\\">||</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    samePoint</span><span style=\\"color:#24292E\\">(l1.start, l2.end) </span><span style=\\"color:#D73A49\\">||</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    samePoint</span><span style=\\"color:#24292E\\">(l1.end, l2.start) </span><span style=\\"color:#D73A49\\">||</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    samePoint</span><span style=\\"color:#24292E\\">(l1.end, l2.end)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  ) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> (</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    signedArea</span><span style=\\"color:#24292E\\">(l1.start, l2.start, l2.end) </span><span style=\\"color:#D73A49\\">!==</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">      signedArea</span><span style=\\"color:#24292E\\">(l1.end, l2.start, l2.end) </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    signedArea</span><span style=\\"color:#24292E\\">(l1.start, l1.end, l2.start) </span><span style=\\"color:#D73A49\\">!==</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">      signedArea</span><span style=\\"color:#24292E\\">(l1.start, l1.end, l2.end)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> function</span><span style=\\"color:#6F42C1\\"> intersectPolygon</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">points</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Array</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">Point</span><span style=\\"color:#24292E\\">>) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> len</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> points.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  for</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">let</span><span style=\\"color:#24292E\\"> i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> len </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#005CC5\\"> 1</span><span style=\\"color:#24292E\\">; i</span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    for</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">let</span><span style=\\"color:#24292E\\"> j </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> i </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#005CC5\\"> 1</span><span style=\\"color:#24292E\\">; j </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> len; j</span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      const</span><span style=\\"color:#005CC5\\"> l1</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Line</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        start: points[i],</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        end: points[(i </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#005CC5\\"> 1</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">%</span><span style=\\"color:#24292E\\"> len]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      const</span><span style=\\"color:#005CC5\\"> l2</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Line</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        start: points[j],</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        end: points[(j </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#005CC5\\"> 1</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">%</span><span style=\\"color:#24292E\\"> len]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      };</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">intersectLine</span><span style=\\"color:#24292E\\">(l1, l2)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br><span class=\\"line-number\\">47</span><br><span class=\\"line-number\\">48</span><br><span class=\\"line-number\\">49</span><br><span class=\\"line-number\\">50</span><br><span class=\\"line-number\\">51</span><br><span class=\\"line-number\\">52</span><br><span class=\\"line-number\\">53</span><br><span class=\\"line-number\\">54</span><br><span class=\\"line-number\\">55</span><br><span class=\\"line-number\\">56</span><br><span class=\\"line-number\\">57</span><br><span class=\\"line-number\\">58</span><br><span class=\\"line-number\\">59</span><br><span class=\\"line-number\\">60</span><br><span class=\\"line-number\\">61</span><br></div></div><h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>简单多边形判定的本质是任意两边是否相交，如果是邻边的话就直接跳过。在复杂度不高的情况下，可以直接使用遍历的方法来实现。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"http://geomalgorithms.com/a09-_intersect-3.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">Intersections of a Set of Segments</a></p>\\n<p><a href=\\"https://bryceboe.com/2006/10/23/line-segment-intersection-algorithm/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Line Segment Intersection Algorithm</a></p>\\n<p><a href=\\"https://github.com/rowanwins/shamos-hoey\\" target=\\"_blank\\" rel=\\"noreferrer\\">shamos-hoey</a></p>\\n"},{"title":"Vue中组件的设计","url":"/posts/2020-07-30-vue-components/","date":"2020-07-30 22:08","tags":["frontend","vue"],"html":"<p>Vue 中组件设计经常遇到复合组件的问题，例如下拉菜单，下拉菜单中我们不仅要实现<code>select</code>元素的功能，还要实现<code>option</code>元素的功能，这样才是一个完整的下拉菜单组件。</p>\\n<h2 id=\\"复合组件中的数据相互访问\\" tabindex=\\"-1\\">复合组件中的数据相互访问 <a class=\\"header-anchor\\" href=\\"#复合组件中的数据相互访问\\" aria-label=\\"Permalink to &quot;复合组件中的数据相互访问&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>复合组件中的数据访问是设计组件的一个重要议题，设计不好会严重影响组件的灵活性。我们拿 Element UI 的组件来举个例子：</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">el-select</span><span style=\\"color:#6F42C1\\"> v-model</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"value\\"</span><span style=\\"color:#6F42C1\\"> placeholder</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"请选择\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;</span><span style=\\"color:#22863A\\">el-option</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    v-for</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"item in options\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    :key</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"item.value\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    :label</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"item.label\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    :value</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"item.value\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  ></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;/</span><span style=\\"color:#22863A\\">el-option</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#22863A\\">el-select</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br></div></div><p>这是一个经典的例子，但是实际使用过程中，我们可能会二次封装组件,例如我们需要给<code>el-option</code>加一些事件或者样式，那我们的代码会变成这样：</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">el-select</span><span style=\\"color:#6F42C1\\"> v-model</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"value\\"</span><span style=\\"color:#6F42C1\\"> placeholder</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"请选择\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;</span><span style=\\"color:#22863A\\">styled-el-option</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    v-for</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"item in options\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    :key</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"item.value\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    :label</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"item.label\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    :value</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"item.value\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  ></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;/</span><span style=\\"color:#22863A\\">styled-el-option</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#22863A\\">el-select</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br></div></div><p><code>styled-el-option</code> 是我们二次封装的组件，里面包含了<code>el-option</code>组件。如果我们使用<code>$parent</code>在<code>el-option</code>组件中访问<code>el-select</code>组件的话，二次封装的情况下就会出错。\\n因为<code>el-option</code>的父组件不再是<code>el-select</code>，而是<code>styled-el-option</code>。正确的数据访问方式是使用<code>provide</code> 和 <code>inject</code>。</p>\\n<h2 id=\\"子组件访问父组件\\" tabindex=\\"-1\\">子组件访问父组件 <a class=\\"header-anchor\\" href=\\"#子组件访问父组件\\" aria-label=\\"Permalink to &quot;子组件访问父组件&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先我们需要在父附件中这样定义：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">provide</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\"> () {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">    'select'</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">this</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><p>然后在子组件中使用<code>inject</code>:</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">inject</span><span style=\\"color:#24292E\\">: [</span><span style=\\"color:#032F62\\">'select'</span><span style=\\"color:#24292E\\">];</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这样子组件就可以访问父组件了，使用<code>provide</code>的好处是不用担心复合组件中的再封装问题，Vue 会自动向上查找。</p>\\n<h2 id=\\"父组件访问子组件\\" tabindex=\\"-1\\">父组件访问子组件 <a class=\\"header-anchor\\" href=\\"#父组件访问子组件\\" aria-label=\\"Permalink to &quot;父组件访问子组件&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Vue 中并没有提供非常方便的查找子组件的功能， 所以目前的方法是在父组件中存储子组件的实例。</p>\\n<p>父组件中定义数据：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">data</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\"> () {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    options: []</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><p>子组件通过<code>inject</code>可以访问父组件，所以：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">created</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  this</span><span style=\\"color:#24292E\\">.select.options.</span><span style=\\"color:#6F42C1\\">push</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">this</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>在创建组件的时候同时传入父组件的<code>data</code>字段中。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>灵活的设计组件才能在实际开发中更方便的使用，一些第三方组件开发的时候没有考虑到二次封装的可能性，直接通过<code>$parent</code>和<code>$children</code>进行数据的更新。导致可用性大大降低。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://vuejs.org/v2/guide/components-edge-cases.html#Dependency-Injection\\" target=\\"_blank\\" rel=\\"noreferrer\\">Dependency Injection</a></p>\\n"}]},"relativePath":"page/14/index.md","filePath":"page/[page].md"}`),l={name:"page/14/index.md"};function p(e,o,r,c,t,i){return n(),a("div")}const d=s(l,[["render",p]]);export{b as __pageData,d as default};
